package com.mohymods.kingdomsmp.economy;
import static org.junit.jupiter.api.Assertions.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import java.util.*;
import java.nio.file.Path;
import java.io.IOException;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
/** Canonical all16 boundary for reusable Master transaction tests, not native earned-progress evidence. */
class LibraryMasterStoreTest {
 @TempDir Path directory;UUID p;
 EconomyStore earnedJourneyman()throws Exception{
  var f=new LibraryJourneymanStoreTest();f.directory=directory;var s=f.earnedApprentice();p=f.p;var admin=UUID.randomUUID();
  for(var quest:List.of(NativeOutputQuests.LIBRARY_FAMILIES,NativeOutputQuests.LIBRARY_MAXIMUM)){var outputs=new LinkedHashMap<UUID,CompoundTag>();int count=quest.equals(NativeOutputQuests.LIBRARY_FAMILIES)?4:2;for(int n=0;n<count;n++){var id=UUID.randomUUID();var item=LibraryJourneymanStoreTest.book(n);s.issueNativeOutput(id,p,quest,item,new NativeBookProof(quest.equals(NativeOutputQuests.LIBRARY_FAMILIES)?1<<n:8,true));outputs.put(id,item);}var pending=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,quest,outputs,count);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));}
  s.approveProfessionInspection(UUID.randomUUID(),admin,p,LibraryFieldGuide.QUEST,"Pure canonical personally observed field guide model");var g=s.prepareLibraryCatalogue(UUID.randomUUID(),p,admin,LibraryGlyphCatalogueStoreTest.items(),"Pure canonical inspected glyph model");s.recoverItem(new EconomyStore.Receipt(s.id(),g.sequence()));var facts=LibrarySpellCatalogueStoreTest.facts();g=s.prepareLibraryCatalogue(UUID.randomUUID(),p,admin,LibrarySpellCatalogue.QUEST,facts.stream().map(LibrarySpellCatalogueStoreTest::item).toList(),facts.stream().map(LibrarySpellCatalogue.Fact::save).toList(),"Pure canonical inspected spell model");s.recoverItem(new EconomyStore.Receipt(s.id(),g.sequence()));
  var a=UUID.randomUUID();var b=UUID.randomUUID();for(int n=0;n<3;n++){var source=UUID.randomUUID();var storage=UUID.randomUUID();var consent=UUID.randomUUID();var output=UUID.randomUUID();var before=worn(source,storage,1);var after=worn(source,storage,2);s.authorizeService(consent,n<2?a:b,p,ServiceWorkState.LIBRARY,storage,source,before);s.issueServiceOutput(output,p,consent,after,1,1);g=s.prepareServiceReturn(UUID.randomUUID(),p,output,after);s.recoverItem(new EconomyStore.Receipt(s.id(),g.sequence()));}s.completeServiceQuest(UUID.randomUUID(),p,ServiceWorkState.LIBRARY);
  var paper=new CompoundTag();paper.putString("id","minecraft:paper");paper.putInt("count",1);for(long period=200;period<=201;period++){g=s.prepareContract(UUID.randomUUID(),p,"librarian","weekly",period,256,128,10000,paper,6);s.recoverItem(new EconomyStore.Receipt(s.id(),g.sequence()));}s.completeCommissionQuest(UUID.randomUUID(),p,"kingdom_smp:librarian/j07",2);s.approveProfessionInspection(UUID.randomUUID(),admin,p,"kingdom_smp:librarian/j08","Pure canonical actual all16Library model boundary");assertEquals(2400,s.professions(p).track(Profession.LIBRARIAN).xp());return s;
 }
 static CompoundTag worn(UUID id,UUID store,int level){var item=new CompoundTag();item.putString("id","minecraft:iron_pickaxe");item.putInt("count",1);var c=new CompoundTag();c.putInt("minecraft:damage",1);var data=new CompoundTag();var marker=new CompoundTag();marker.putUUID("store",store);marker.putUUID("id",id);data.put(RepairService.KEY,marker);c.put("minecraft:custom_data",data);var enchant=new CompoundTag();var levels=new CompoundTag();levels.putInt("minecraft:efficiency",level);enchant.put("levels",levels);c.put("minecraft:enchantments",enchant);item.put("components",c);return item;}
 @Test void maximumCompendiumRejectsMonocultureAndNonMaximumThenRecoversExactlyOnce()throws Exception{
  var s=earnedJourneyman();assertEquals(8,ApprovedProfessionContent.get(NativeOutputQuests.LIBRARY_COMPENDIUM).minimumTier());assertEquals(6,com.mohymods.kingdomsmp.kingdom.AlphaScope.questTier(NativeOutputQuests.LIBRARY_COMPENDIUM));assertThrows(IllegalArgumentException.class,()->s.issueNativeOutput(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_COMPENDIUM,LibraryJourneymanStoreTest.book(0),new NativeBookProof(1,false)));
  Map<UUID,CompoundTag> bad=new LinkedHashMap<>(),good=new LinkedHashMap<>();for(int n=0;n<6;n++){var item=LibraryJourneymanStoreTest.book(n);var id=UUID.randomUUID();s.issueNativeOutput(id,p,NativeOutputQuests.LIBRARY_COMPENDIUM,item,new NativeBookProof(n%2==0?2:8,true));bad.put(id,item);id=UUID.randomUUID();s.issueNativeOutput(id,p,NativeOutputQuests.LIBRARY_COMPENDIUM,item,new NativeBookProof(1<<(n%3),true));good.put(id,item);}assertThrows(IllegalStateException.class,()->s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_COMPENDIUM,bad,6));var pending=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_COMPENDIUM,good,6);long sequence=pending.sequence();var broken=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("Master book native receipt after rename");});assertThrows(IOException.class,()->broken.recoverItem(new EconomyStore.Receipt(s.id(),sequence)));var restored=EconomyStore.open(directory);assertFalse(restored.recoverItem(new EconomyStore.Receipt(s.id(),sequence)));assertEquals(2700,restored.professions(p).track(Profession.LIBRARIAN).xp());assertEquals(6,restored.spentNativeOutputs(p,NativeOutputQuests.LIBRARY_COMPENDIUM));assertThrows(IllegalStateException.class,()->restored.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_COMPENDIUM,good,6));restored.archive(p,"Master compendium model");assertEquals(restored.professions(p),EconomyStore.open(directory).professions(p));
 }
 @Test void diverseSelectionUsesDistinctPhysicalPositionsAndBoundedCoverage(){var masks=List.of(2,2,2,8,8,8,1,1);assertTrue(NativeBookProof.selectDiverse(masks.subList(0,6),6).isEmpty());var selected=NativeBookProof.selectDiverse(masks,6);assertEquals(6,selected.size());assertEquals(6,new HashSet<>(selected).size());assertTrue(Integer.bitCount(selected.stream().mapToInt(masks::get).reduce(0,(a,b)->a|b))>=3);assertThrows(IllegalArgumentException.class,()->NativeBookProof.selectDiverse(Collections.nCopies(37,1),6));}
 @Test void alphaArchivesUseSixDistinctInputsAndPreserveEarlierCatalogueSchemas()throws Exception{
  var s=earnedJourneyman();var admin=UUID.randomUUID();var glyphs=new ArrayList<>(LibraryGlyphCatalogueStoreTest.items());for(var name:List.of("invisibility","slowfall")){var n=new CompoundTag();n.putString("id","ars_nouveau:glyph_"+name);n.putInt("count",1);glyphs.add(n);}assertThrows(IllegalArgumentException.class,()->s.prepareLibraryCatalogue(UUID.randomUUID(),p,admin,LibraryGlyphCatalogue.MASTER,glyphs.subList(0,4),List.of(),"Earlier quantity cannot satisfy Master alpha archive"));var pending=s.prepareLibraryCatalogue(UUID.randomUUID(),p,admin,LibraryGlyphCatalogue.MASTER,glyphs,List.of(),"Pure canonical alpha6native Tier2archive model");s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));assertEquals(2700,s.professions(p).track(Profession.LIBRARIAN).xp());var facts=new ArrayList<>(LibrarySpellCatalogueStoreTest.facts());facts.add(new LibrarySpellCatalogue.Fact("irons_spellbooks:firebolt",6,"RARE"));facts.add(new LibrarySpellCatalogue.Fact("irons_spellbooks:heal",3,"RARE"));var items=facts.stream().map(LibrarySpellCatalogueStoreTest::item).toList();var proof=facts.stream().map(LibrarySpellCatalogue.Fact::save).toList();assertThrows(IllegalArgumentException.class,()->s.prepareLibraryCatalogue(UUID.randomUUID(),p,admin,LibrarySpellCatalogue.MASTER,items.subList(0,4),proof.subList(0,4),"Earlier spell quantity cannot satisfy Master archive"));pending=s.prepareLibraryCatalogue(UUID.randomUUID(),p,admin,LibrarySpellCatalogue.MASTER,items,proof,"Pure canonical alpha6RAREarchive model");s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));assertEquals(3000,s.professions(p).track(Profession.LIBRARIAN).xp());assertTrue(s.professions(p).track(Profession.LIBRARIAN).completedQuestIds().containsAll(Set.of(LibraryGlyphCatalogue.QUEST,LibrarySpellCatalogue.QUEST,LibraryGlyphCatalogue.MASTER,LibrarySpellCatalogue.MASTER)));s.archive(admin,"Old and alpha Master catalogue model");assertEquals(s.professions(p),EconomyStore.open(directory).professions(p));assertEquals(8,ApprovedProfessionContent.get(LibraryGlyphCatalogue.MASTER).minimumTier());assertEquals(6,com.mohymods.kingdomsmp.kingdom.AlphaScope.questTier(LibraryGlyphCatalogue.MASTER));
 }

 @Test void masterServicesRequireFourNewReturnedSourcesAndCannotReuseJourneymanRights()throws Exception{
  var s=earnedJourneyman();var a=UUID.randomUUID();var b=UUID.randomUUID();assertEquals(3,s.serviceWork().jobs(p,ServiceWorkState.LIBRARY));assertEquals(0,s.serviceWork().jobs(p,ServiceWorkState.LIBRARY_MASTER));assertThrows(IllegalStateException.class,()->s.completeServiceQuest(UUID.randomUUID(),p,ServiceWorkState.LIBRARY_MASTER));for(int n=0;n<4;n++){var source=UUID.randomUUID();var storage=UUID.randomUUID();var consent=UUID.randomUUID();var output=UUID.randomUUID();s.authorizeService(consent,n<2?a:b,p,ServiceWorkState.LIBRARY_MASTER,storage,source,worn(source,storage,1));s.issueServiceOutput(output,p,consent,worn(source,storage,2),1,1);var pending=s.prepareServiceReturn(UUID.randomUUID(),p,output,worn(source,storage,2));s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));if(n<3)assertThrows(IllegalStateException.class,()->s.completeServiceQuest(UUID.randomUUID(),p,ServiceWorkState.LIBRARY_MASTER));}s.completeServiceQuest(UUID.randomUUID(),p,ServiceWorkState.LIBRARY_MASTER);assertEquals(2700,s.professions(p).track(Profession.LIBRARIAN).xp());assertEquals(4,s.serviceWork().jobs(p,ServiceWorkState.LIBRARY_MASTER));assertEquals(3,s.serviceWork().jobs(p,ServiceWorkState.LIBRARY));assertEquals(2,s.itemMailbox(a).size());assertEquals(2,s.itemMailbox(b).size());assertThrows(IllegalStateException.class,()->s.completeServiceQuest(UUID.randomUUID(),p,ServiceWorkState.LIBRARY_MASTER));s.archive(p,"Separate Master current-owner service model");assertEquals(s.professions(p),EconomyStore.open(directory).professions(p));
 }

}
